CREATE TABLE IF NOT EXISTS businesses(id INTEGER PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, nit TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', receipt_width INTEGER NOT NULL DEFAULT 80);
INSERT OR IGNORE INTO businesses(id,name,kind) VALUES(1,'Mini market','market'),(2,'Ferretería','hardware');
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','cashier')), businesses TEXT NOT NULL DEFAULT '[1,2]', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), sku TEXT NOT NULL, barcode TEXT, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL CHECK(unit IN ('und','g','m')), price INTEGER NOT NULL CHECK(price>=0), price_basis INTEGER NOT NULL DEFAULT 1000, image TEXT NOT NULL DEFAULT '', min_stock INTEGER NOT NULL DEFAULT 0, perishable INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, UNIQUE(business_id,sku), UNIQUE(business_id,barcode));
CREATE INDEX IF NOT EXISTS idx_products_business ON products(business_id,active);
CREATE TABLE IF NOT EXISTS lots(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), product_id INTEGER NOT NULL REFERENCES products(id), code TEXT NOT NULL, expires TEXT, qty INTEGER NOT NULL CHECK(qty>=0), cost INTEGER NOT NULL CHECK(cost>=0), cost_basis INTEGER NOT NULL DEFAULT 1000, supplier TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '', created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_lots_product ON lots(business_id,product_id,expires);
CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), name TEXT NOT NULL, document TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', credit_limit INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_customers_business ON customers(business_id);
CREATE TABLE IF NOT EXISTS cash_sessions(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), user_id INTEGER NOT NULL REFERENCES users(id), opened TEXT NOT NULL, opening INTEGER NOT NULL CHECK(opening>=0), closed TEXT, counted INTEGER, expected INTEGER, note TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS idx_open_cash ON cash_sessions(business_id) WHERE closed IS NULL;
CREATE TABLE IF NOT EXISTS quotes(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), customer_id INTEGER REFERENCES customers(id), user_id INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL, valid_until TEXT NOT NULL, lines TEXT NOT NULL, total INTEGER NOT NULL, converted_sale INTEGER, note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sales(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), number INTEGER NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), cash_id INTEGER NOT NULL REFERENCES cash_sessions(id), customer_id INTEGER REFERENCES customers(id), created TEXT NOT NULL, total INTEGER NOT NULL, cost INTEGER NOT NULL, debt INTEGER NOT NULL DEFAULT 0, original_debt INTEGER NOT NULL DEFAULT 0, due TEXT, status TEXT NOT NULL DEFAULT 'active', void_reason TEXT, request_id TEXT NOT NULL, quote_id INTEGER REFERENCES quotes(id), UNIQUE(business_id,number), UNIQUE(business_id,request_id));
CREATE INDEX IF NOT EXISTS idx_sales_business_date ON sales(business_id,created);
CREATE TABLE IF NOT EXISTS sale_lines(id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES sales(id), product_id INTEGER NOT NULL REFERENCES products(id), name TEXT NOT NULL, sku TEXT NOT NULL, unit TEXT NOT NULL, qty INTEGER NOT NULL CHECK(qty>0), price INTEGER NOT NULL, price_basis INTEGER NOT NULL DEFAULT 1000, total INTEGER NOT NULL, cost INTEGER NOT NULL, allocations TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), sale_id INTEGER REFERENCES sales(id), cash_id INTEGER NOT NULL REFERENCES cash_sessions(id), user_id INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL, method TEXT NOT NULL, amount INTEGER NOT NULL, kind TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_payments_cash ON payments(cash_id);
CREATE TABLE IF NOT EXISTS cash_moves(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), cash_id INTEGER NOT NULL REFERENCES cash_sessions(id), user_id INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL, amount INTEGER NOT NULL, reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_moves(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), product_id INTEGER NOT NULL REFERENCES products(id), lot_id INTEGER NOT NULL REFERENCES lots(id), user_id INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL, qty INTEGER NOT NULL, kind TEXT NOT NULL, reference TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_stock_moves_business ON stock_moves(business_id,created);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, business_id INTEGER REFERENCES businesses(id), user_id INTEGER REFERENCES users(id), created TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS email_queue(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), sale_id INTEGER NOT NULL REFERENCES sales(id), recipient TEXT NOT NULL, created TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', error TEXT NOT NULL DEFAULT '');
